steps.body:
`std::binary_search` and `std::lower_bound` from the Iterators lesson halve a sorted range for you. Writing the loop yourself matters when the data isn't a plain ascending vector, or when you search for something other than a stored value. Keep the range `lo` to `hi`, look at the middle, and throw away the half that can't hold the target:

```cpp
int search(const std::vector<int>& a, int target) {
    int lo = 0;
    int hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) {
            return mid;
        } else if (a[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

std::cout << search({2, 4, 7, 9}, 7) << ' ' << search({2, 4, 7, 9}, 5) << '\n';   // 2 -1
```

`while (lo <= hi)` runs while the range holds at least one index, and every pass shrinks it, so the loop always ends. Keep `lo` and `hi` as `int`: on an empty vector `hi` starts at -1, which a `std::size_t` can't hold. `lo + (hi - lo) / 2` finds the middle without computing `lo + hi`, which overflows an `int` when both are near 2 billion.

For a vector sorted from high to low, flip the two comparisons: go right when `a[mid]` is bigger than the target.

example.code:
#include <algorithm>
#include <iostream>
#include <vector>

int search(const std::vector<int>& a, int target) {
    int lo = 0;
    int hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) {
            return mid;
        } else if (a[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }
    int q = 0;
    std::cin >> q;
    for (int t = 0; t < q; ++t) {
        int target = 0;
        std::cin >> target;
        int found = search(a, target);
        if (found >= 0) {
            std::cout << target << ": found at " << found << '\n';
        } else {
            auto spot = std::lower_bound(a.begin(), a.end(), target);
            std::cout << target << ": missing, insert at " << (spot - a.begin()) << '\n';
        }
    }
    return 0;
}

