    for (int w : weights) {
        if (load + w > capacity) {
            ++days;
            load = 0;
        }
        load += w;
    }
    return days;
}

int main() {
    int n = 0;
    int d = 0;
    std::cin >> n >> d;
    std::vector<int> weights(n);
    for (int i = 0; i < n; ++i) {
